// Case-insensitive lookup that also strips parenthetical annotations like "Articles (type=Service)".
export function getTableColumns(name: string): TableColumn[] | undefined {
  const clean = name.replace(/\s*\(.*\)$/, "").trim();
  if (TABLE_COLUMNS[clean]) return TABLE_COLUMNS[clean];
  const lc = clean.toLowerCase();
  for (const k of Object.keys(TABLE_COLUMNS)) if (k.toLowerCase() === lc) return TABLE_COLUMNS[k];
  return undefined;
}
